INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Datenübertragung dasselbe wie Datenverarbeitung?', 2, '[{"text": "Nein", "correct": true, "because": "Übertragung bewegt Daten, Verarbeitung ändert sie"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Konzepte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Datenübertragung?', 3, '[{"text": "Daten zwischen Systemen bewegen", "correct": true, "because": "Kommunikation ermöglichen"}, {"text": "Hardware reparieren", "correct": false, "because": "Kein Hardware-Fokus"}, {"text": "Software entwickeln", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Medien werden für Datenübertragung genutzt?', 5, '[{"text": "Kabel", "correct": true, "because": "z. B. Ethernet"}, {"text": "Funk", "correct": true, "because": "z. B. WLAN"}, {"text": "Papier", "correct": false, "because": "Kein digitales Medium"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenübertragung kann drahtlos sein. b) Sie ist immer sicher.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Datenübertragung?', 4, '[{"text": "Übertragungsprotokoll", "correct": false, "because": "Definiert Methode"}, {"text": "Bandbreite", "correct": false, "because": "Beeinflusst Geschwindigkeit"}, {"text": "Bildschirmgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datenübertragung nur über Netzwerke erfolgt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokal möglich"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wird oft für Datenübertragung im Internet genutzt?', 3, '[{"text": "TCP/IP", "correct": true, "because": "Standardprotokoll"}, {"text": "HTML", "correct": false, "because": "Webformat"}, {"text": "SQL", "correct": false, "because": "Datenbankabfrage"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Datenübertragung?', 5, '[{"text": "Latenz", "correct": true, "because": "Verzögerung wirkt"}, {"text": "Bandbreite", "correct": true, "because": "Kapazität entscheidend"}, {"text": "Monitorauflösung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Datenübertragung kann verschlüsselt sein. b) Sie ist immer drahtgebunden. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch drahtlos möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Datenübertragung?', 4, '[{"text": "Übertragungsmedium", "correct": false, "because": "Physisch oder drahtlos nötig"}, {"text": "Protokoll", "correct": false, "because": "Regelt Übertragung"}, {"text": "Küchenzeile", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Datenübertragung immer schnell?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Faktoren"}, {"text": "Ja", "correct": false, "because": "Variabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle sichern die Datenübertragung?', 4, '[{"text": "HTTPS", "correct": true, "because": "Verschlüsselt"}, {"text": "SSL/TLS", "correct": true, "because": "Sicherheitsprotokolle"}, {"text": "HTML", "correct": false, "because": "Kein Sicherheitsprotokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Datenübertragung keine Rolle spielt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kritisch für Kommunikation"}, {"text": "Ja", "correct": false, "because": "Wichtig für Systeme"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Datenübertragung?', 3, '[{"text": "Sicherheit", "correct": true, "because": "Schutz vor Abgriff"}, {"text": "Minimale Kosten", "correct": false, "because": "Qualität wichtiger"}, {"text": "Schnelle Installation", "correct": false, "because": "Leistung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenübertragung kann gestört werden. b) Sie ist immer verlustfrei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verluste möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien verbessern die Datenübertragung?', 5, '[{"text": "Glasfaser", "correct": true, "because": "Hohe Geschwindigkeit"}, {"text": "Kompression", "correct": true, "because": "Weniger Datenvolumen"}, {"text": "Texteditor", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Datenübertragung unwichtig?', 3, '[{"text": "Übertragungsrate", "correct": false, "because": "Bestimmt Geschwindigkeit"}, {"text": "Protokoll", "correct": false, "because": "Regelt Übertragung"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Datenübertragung ohne Protokoll erfolgen?', 3, '[{"text": "Nein", "correct": true, "because": "Regeln nötig"}, {"text": "Ja", "correct": false, "because": "Protokoll erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datenübertragung nur über Netzwerke läuft?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokal möglich"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Verschlüsselung?', 4, '[{"text": "Sichert Daten", "correct": true, "because": "Schutz vor Abgriff"}, {"text": "Erhöht Bandbreite", "correct": false, "because": "Kein Netzwerkeffekt"}, {"text": "Verbessert Grafik", "correct": false, "because": "Irrelevant"}]');
